export type SamplePack = 'problems' | 'complete'

export function samplePackUrl(file: SamplePackFile): string {
  const folder = file.key.startsWith('fix-') ? 'samples/fixes' : file.key.startsWith('complete-') ? 'samples/complete' : 'samples'
  return `${import.meta.env.BASE_URL}${folder}/${encodeURIComponent(file.fileName)}`
}

export function findSampleFile(key: string | undefined): SamplePackFile | undefined {
  return key ? [...SAMPLE_PACK_FILES, ...SAMPLE_FIX_FILES].find((file) => file.key === key) : undefined
}
